scripts/migrations/data_20260819134359_2026-08-19-research-batch-01-room-acoustic-performance.sql:52:INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (1, 6, 'room-acoustic-performance', NULL, 'ADMITTED', 'Listening beyond the noise: IPA of mental fatigue and restoration in neurodivergent students acoustical environments', '10.1080/23311886.2026.2645738', 'RESOLVED', 1, 0, NULL, 'RESOLVED: re-described from the source record. STAGED HYPOTHESIS was ''evidence that neurodivergent students need lower noise levels''. Wrong, and corrected here: the themes are Acoustical Control as Cognitive Safety and Restoration is Not Silence - imposed silence was experienced as emotionally taxing, and predictability plus personal control ranked above level. Admitted as REF-00968. The hypothesis would have inverted the requirement class.', 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19');
scripts/migrations/data_20260819134359_2026-08-19-research-batch-01-room-acoustic-performance.sql:53:INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (2, 1, 'room-acoustic-performance', NULL, 'REHOME', 'Experiences of Sensory Overload and Communication Barriers by Autistic Adults in Health Care Settings', '10.1089/aut.2020.0074', 'RESOLVED', 1, 1, 'Off-slug: healthcare-setting sensory environment, not room acoustic performance as a parameter.', 'Real Co-1 material carrying a harm finding (avoidance of care). Belongs to a healthcare-environment slug. Rehomed rather than admitted here so it is not lost.', 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19');
