scripts/migrations/data_20260822053540_2026-08-22-research-batch-02-room-acoustic-performance.sql:67:INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (31, 13, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Ghazanfar 2026 - Impact of classroom acoustic conditions on children with ASD (Urbanization, Sustainability and Society)', 'DOI not captured; retrieve via Crossref title search', 'UNVERIFIED', 1, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15), highest-value lead in this batch: an A-B-A single-case design that explicitly TESTS RT = 0.4 s Tmf with ASD children, RT modulated 1.1 -> 0.39 s. If it holds on full text this is the first on-parameter, population-specific THRESHOLD TEST for AUT - precisely what batch 1 declared did not exist. n=4, so small. tier_guess 1 is a GUESS about design, not a grade. [UNVERIFIED-QUANT]', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
scripts/migrations/data_20260822053540_2026-08-22-research-batch-02-room-acoustic-performance.sql:68:INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (32, 13, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Caldas et al. 2023 - Measurements of classroom acoustic conditions in which young neurodiverse persons learn, Sao Paulo and Nebraska (JASA)', 'JASA 2023; DOI to retrieve', 'UNVERIFIED', 1, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15): measured RT, C50, STI and S/N in rooms built for autistic pupils across two countries. On-parameter and on-population; unit of study is the ROOM, so a population match would cap at PARTIAL.', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
scripts/migrations/data_20260822053540_2026-08-22-research-batch-02-room-acoustic-performance.sql:69:INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (33, 13, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Ueno et al. 2019 - A field study on the acoustic environment of special-needs education classrooms (Building Acoustics)', 'Building Acoustics 2019', 'UNVERIFIED', 3, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15): teacher survey plus observation in special-needs classrooms, and a constructed calming space of sound-absorbing material. Bears on A-16 sensory/quiet room provision as much as on RT60 - possible REHOME at resolution.', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
scripts/migrations/data_20260822053540_2026-08-22-research-batch-02-room-acoustic-performance.sql:70:INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (34, 13, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Tardini et al. 2025 - Survey of national target values on classroom acoustics (Building and Environment)', 'Building and Environment 2025', 'UNVERIFIED', 2, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15): 50+ country survey reporting 0.6-0.7 s unoccupied RT and 35 dBA. Directly comparable to the 16-jurisdiction table in references/bpc-reasoning/room-acoustic-performance.md, which is Pass-1 with citation-grade verification PENDING - this could verify or refute a dozen of its cells at once. [UNVERIFIED-QUANT]', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
scripts/migrations/data_20260822053540_2026-08-22-research-batch-02-room-acoustic-performance.sql:71:INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (35, 10, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Talebzadeh et al. 2023 - Everyday acoustic environments and challenging behaviour in dementia: participatory observation in nursing homes (IJERPH)', 'IJERPH 2023', 'UNVERIFIED', 1, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15): 24/7 participatory observation, 35 residents. Possible Co-1 CANDIDATE for DEM - participatory method is the same warrant OD-D is testing on the AUT side. Would be the first Co-1 the DEM population has on this slug. tier_guess 1 records the Co-1 hypothesis, not a grade.', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
scripts/migrations/data_20260822053540_2026-08-22-research-batch-02-room-acoustic-performance.sql:72:INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (36, 10, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Mu et al. 2021 - Acoustic environment of comprehensive activity spaces in nursing homes, Harbin (Applied Acoustics)', 'Applied Acoustics 2021', 'UNVERIFIED', 3, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15): carries an on-parameter threshold for older adults - subjective comfort declined above RT 4 s or 65 dB(A). An order of magnitude looser than any classroom target, which is a finding about setting-dependence rather than a contradiction. [UNVERIFIED-QUANT]', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
scripts/migrations/data_20260822053540_2026-08-22-research-batch-02-room-acoustic-performance.sql:73:INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (37, 11, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Deng et al. 2023 - The acoustic environment in typical hospital wards in China (Applied Acoustics)', 'Applied Acoustics 2023', 'UNVERIFIED', 3, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15): measured ward RT 0.34-0.67 s (500 Hz-1 kHz) and 24 h Leq 57.3-63.9 dBA. First on-parameter measurement retrieved for a health-care ward setting, relevant to MH and to clinical rooms this slug serves. [UNVERIFIED-QUANT]', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');

20:INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-045', 'SW', 'P3', 'CLOSED-FIXED', 'governance', NULL, 'resolve-candidate COULD NOT WRITE suggested_slug, so a REHOME disposition could not say where the candidate belongs. Found by an independent adversarial pass on batch 20: candidate 117 was re-described as rehomed to stair-ramp-threshold-biomechanics-accessibility while its typed suggested_slug still named accessible-circulation-geometry, the slug it was found under -- the prose and the only joinable column disagreeing. CLAUDE.md section 4: a column the CLI cannot reach is a coverage bug, not a licence for hand SQL. FIXED IN THE SAME BATCH: resolve-candidate takes --suggested-slug with --disposition REHOME only, validates it against slugs, and records the replaced value in the notes tail. Derive whether any REHOME row still points back at its origin: select candidate_id, found_under_slug, suggested_slug from search_candidates where disposition=''REHOME''.', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL, NULL, NULL, NULL, NULL);
21:INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-046', 'SW', 'P2', 'CLOSED-FIXED', 'governance', NULL, 'NO VERB COULD ATTACH AN ADMISSION TO AN EXISTING SEARCH. search_admissions is the one carrier of which search admitted a source, and its only writer was log-search --admitted-ref-id, which attaches an admission only to a search logged in the same call. A source admitted in a later batch from a staged candidate therefore could not point back at the search that surfaced it, although integrity check S01 states that the surfacing search and the admitting search are the same event (batch 17''s candidates 107/108 on exec 77 are the precedent). research_protocol_audit then reported REF-01007 and REF-01008 as admitted by no search. Batch 20 first read that as the audit''s case (b) and wrote no edge; an independent adversarial pass sustained it as case (a) plus a writer gap. FIXED IN THE SAME BATCH: db.py link-admission writes the edge ONLY when a search_candidates row already records both ends (that candidate''s exec_id and resolved_ref_id, disposition ADMITTED) and refuses otherwise, so it restates a recorded fact and cannot attribute a source to an arbitrary search. Applied to (91, REF-01007) and (90, REF-01008).', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL, NULL, NULL, NULL, NULL);
22:INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-047', 'SW', 'P3', 'CLOSED-FIXED', 'governance', NULL, 'TWO OWNER RULINGS OF 2026-09-25 HAD NO WRITER TO APPLY THEM. (1) Re-grading an R13 population match: add-population-match deliberately allows a SECOND row so that a dissent reads as a contest, but a ruling is not a dissent, and nothing could move an existing grade. (2) Narrowing a term''s definition: nothing could write `terms` after add-term. Both are coverage bugs under CLAUDE.md section 4. FIXED IN THE SAME BATCH: amend-population-match (grade checked against the column''s own CHECK; the replaced grade and the reason appended to mismatch_note) and amend-term (definition or scope_note only -- canonical_en is a vocabulary decision -- with the replaced text and the reason appended to scope_note, the row''s only free-text column).', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL, NULL, NULL, NULL, NULL);
23:INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-048', 'AUDT', 'P2', 'OPEN', 'governance', NULL, 'v_value_independence COUNTS ABSENCES AS INDEPENDENT ROOTS. The view counts DISTINCT COALESCE(root_ref_id, root_id) over rows whose root_type is measurement_primary, participatory_finding or derived_calculation, and never looks at claim_type. A row with claim_type ''absent'' asserts that its source states NO value, yet it adds a root to the parameter''s independent-root count exactly as a measured value does. Batch 20 made it worse: REF-01007 (extraction 59, absent-confirmed) is a new root that measures nothing on the parameter. Raised by an independent adversarial pass (finding #9) and WITHHELD from repair in batch 20 pending an owner decision on how independence should be counted; the view is NOT redefined here. Derive the absence-only roots rather than trusting any list: select coalesce(root_ref_id, root_id) root, count(*) n from source_value_extractions where parameter_id=3 and root_type in (''measurement_primary'',''participatory_finding'',''derived_calculation'') group by root having sum(claim_type <> ''absent'') = 0. Compare select * from v_value_independence where parameter_id=3.', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL, NULL, NULL, NULL, NULL);
24:INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-049', 'RP', 'P2', 'OPEN', 'multilingual-research', NULL, 'BATCH 20''s R1 (Co-1 / T2) LEG WAS A THIN DISCHARGE OF R1, NOT A FULL ONE. It ran three queries (exec 92-94): English only, one biomedical full-text index (Europe PMC), no DPO or disability-organisation channel, no non-English vocabulary, no grey-literature route. research_batch_dod R1 passes when Co-1-targeted searches exist, which is why the gate was green; an independent adversarial pass (finding #20) sustained that the leg did not do what R1 exists for -- ''Co-1 / T2 / Co-2 pass FIRST'', co-primary with T1 under CRPD 4.3. FOR A FUTURE BATCH, not a repair: a Co-1 pass on ramp gradient that reaches DPO and user-led outputs in more than one language and more than one kind of index. Candidate 126 (Mactaggart 2024, a participatory audit staged by this leg) is the strongest lead it produced.', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL, NULL, NULL, NULL, NULL);

